import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-123: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short123', durationInSeconds: 36.1, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short123: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(33.0);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: '2.5 PRO GONE' }, { text: 'DECEMBER 1', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.2)}>
        <CoverImage src="projects/short-123/cover.png" out={secToFrame(3.2) - 10} />
        <HookTitle hold onDark kicker="GEMINI API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(13.0)}>
        <ToolCard name="Dec 1, 2026" tagline="Requests auto-route." chip="SWAP" at={secToFrame(3.2) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="gemini-2.5-pro" v="" />
            <Line k="routes to" v="gemini-3.8-flash" good />
            <Line k="billed at" v="Flash rates" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(17.7)}>
        <ToolCard name="Gemini 2.5 Pro" tagline="Per 1M tokens." chip="$1.25 / $10" at={secToFrame(13.0) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input" v="$1.25" />
            <Line k="output" v="$10.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(23.3)}>
        <ToolCard name="Gemini 3.8 Flash" tagline="Per 1M tokens." chip="$0.75 / $3.75" at={secToFrame(17.7) - 2}>
          <Panel>
            <Line k="input" v="$0.75" />
            <Line k="output" v="$3.75" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(26.2)}>
        <ToolCard name="Output ~2.7x cheaper" tagline="Through Dec 31." chip="2.7X" at={secToFrame(23.3) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="2.5 Pro out" v="$10.00" bad />
            <Line k="3.8 Flash out" v="$3.75" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="But on Jan 1, 2027" tagline="Flash prices double." chip="$1.50 / $7.50" at={secToFrame(26.2) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input" v="$0.75 > $1.50" bad />
            <Line k="output" v="$3.75 > $7.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-123/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="GEMINI API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Check your model name.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short123;
